function Button({ className = '', tone = 'primary', ...props }: ButtonProps) {
  const styles = tone === 'primary' ? 'bg-primary text-primary-foreground hover:brightness-105 shadow-[0_8px_20px_hsl(var(--primary)/.18)]' : tone === 'outline' ? 'border border-border bg-card text-foreground hover:bg-muted' : 'bg-transparent text-muted-foreground hover:bg-muted hover:text-foreground';
  return <button data-testid={props['data-testid']} className={`inline-flex items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-sm font-semibold transition-all duration-200 active:scale-[.98] ${styles} ${className}`} {...props} />;
}

function LogoMark() {
  return <div className="relative flex h-9 w-9 items-center justify-center rounded-xl bg-accent text-foreground" data-testid="logo-mark"><Radar size={19} strokeWidth={2.5} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-primary" /></div>;
}

