function PageIntro({ kicker, title, description, action }: { kicker: string; title: ReactNode; description?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div className="animate-rise"><div className="font-mono-ui text-[10px] font-bold uppercase tracking-[.22em] text-primary">{kicker}</div><h1 className="mt-2 text-4xl tracking-[-.04em] md:text-[46px]">{title}</h1>{description && <p className="mt-2 max-w-xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action && <div className="animate-rise animate-rise-delay-1">{action}</div>}</div>;
}
function Card({ children, className = '', testId }: { children: ReactNode; className?: string; testId?: string }) { return <section className={`rounded-2xl border border-card-border bg-card shadow-[var(--shadow-soft)] ${className}`} data-testid={testId}>{children}</section>; }
function SectionTitle({ title, meta, action }: { title: string; meta?: string; action?: ReactNode }) { return <div className="mb-4 flex items-center justify-between"><div><h2 className="text-[15px] font-bold tracking-tight">{title}</h2>{meta && <p className="mt-0.5 text-xs text-muted-foreground">{meta}</p>}</div>{action}</div>; }
function ProgressBar({ value, color = 'bg-primary' }: { value: number; color?: string }) { return <div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${color} transition-all duration-500`} style={{ width: `${value}%` }} /></div>; }
function Sparkline() { return <svg viewBox="0 0 210 58" className="h-14 w-full" preserveAspectRatio="none" aria-label="Skill score growth chart" data-testid="chart-skill-trend"><path d="M0 47 C14 46, 20 39, 34 41 S54 45, 65 33 S83 36, 96 28 S110 34, 124 22 S141 25, 153 19 S169 21, 181 12 S198 17, 210 4" fill="none" stroke="hsl(var(--primary))" strokeWidth="2.5" /><path d="M0 47 C14 46, 20 39, 34 41 S54 45, 65 33 S83 36, 96 28 S110 34, 124 22 S141 25, 153 19 S169 21, 181 12 S198 17, 210 4 V58 H0Z" fill="hsl(var(--primary) / .09)" /><circle cx="210" cy="4" r="3.5" fill="hsl(var(--accent))" stroke="hsl(var(--card))" strokeWidth="2" /></svg>; }

